/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void dst_err_add (Dst_Error_Code code)
{  

  UInt8 ptr = (dst_vars.err.count % DST_ERR_BUFF_SIZE) ;
 
  dst_vars.err.code[ptr] = code ;

  dst_vars.err.count++ ;
  
  dst_err_save() ;
}


